"math_port_options_function_destination_and_setter"_test=[] {
op::Context c; DiagnosticsGuard diagnostics_guard;
std::vector<std::u16string> warnings; op::OPTIONS.invalidOption=op::InvalidOption::warn;
op::OPTIONS.warningSink=[&](std::u16string message){warnings.push_back(std::move(message));};
auto fn=c.function(u"opaque");
auto nested=c.object();
c.set(op::Value(nested),op::Key(std::u16string{char16_t(0x78)}),op::Value(number(0x3ff0000000000000ULL)));
auto dst=c.object();
auto src=c.object();
c.set(op::Value(dst),op::Key(std::u16string{char16_t(0x76),char16_t(0x61),char16_t(0x6c),char16_t(0x75),char16_t(0x65)}),op::Value(fn));
c.set(op::Value(src),op::Key(std::u16string{char16_t(0x76),char16_t(0x61),char16_t(0x6c),char16_t(0x75),char16_t(0x65)}),op::Value(nested));
auto result_100=op::insert(c,op::Value(dst),op::Value(src),false);
expect(same(result_100,op::Value(dst)));
auto result_101=c.get(op::Value(fn),op::Key(u"x"));
expect(same(result_101,op::Value(number(0x3ff0000000000000ULL))));
int reads=0,writes=0;
auto g=c.function(u"g",[&](op::Context&,op::Value,std::span<const op::Value>){++reads;return op::Value(9);});
auto s=c.function(u"s",[&](op::Context&,op::Value,std::span<const op::Value>){++writes;return op::Value{};});
auto p=c.object();
c.define(p,op::Key(std::u16string{char16_t(0x78)}),op::Descriptor::access(g,s,true,true));
auto target=c.objectWithPrototype(p);
auto access=c.object();
c.define(access,op::Key(std::u16string{char16_t(0x78)}),op::Descriptor::access(g,std::nullopt,true,true));
auto result_102=op::insert(c,op::Value(target),op::Value(access),false);
expect(same(result_102,op::Value(target)));
expect(bool(reads==2 && writes==1)); expect(!c.hasOwn(op::Value(target),op::Key(u"x")));
expect(bool(warnings==std::vector<std::u16string>{}));
};
